CREATE SCHEMA IF NOT EXISTS commerce AUTHORIZATION spms_owner;

CREATE TABLE commerce.tender_definition (
    tender_definition_id           uuid NOT NULL DEFAULT core.uuid_v7(),
    tenant_id                      uuid NOT NULL,
    property_id                    uuid,
    tender_code                    text NOT NULL,
    tender_name                    text NOT NULL,
    tender_type                    text NOT NULL,
    currency_code                  char(3),
    external_mapping_id            uuid,
    status                         text NOT NULL DEFAULT 'Active',
    effective_from                 timestamptz NOT NULL DEFAULT now(),
    effective_to                   timestamptz,
    source_system                  text NOT NULL DEFAULT 'Spa',
    source_key                     text,
    version                        integer NOT NULL DEFAULT 1,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT tender_definition_pkey PRIMARY KEY (tender_definition_id),
    CONSTRAINT tender_definition_tender_type_ck CHECK (tender_type IN ('Card', 'Cash', 'RoomCharge', 'GiftCard', 'MemberAccount', 'External')),
    CONSTRAINT tender_definition_currency_code_ck CHECK (currency_code ~ '^[A-Z]{3}$'),
    CONSTRAINT tender_definition_version_ck CHECK (version >= 1),
    CONSTRAINT tender_definition_tenant_identity_uq UNIQUE (tenant_id, tender_definition_id),
    CONSTRAINT tender_definition_status_known CHECK (status IN ('Active', 'Retired')),
    CONSTRAINT tender_definition_effective_range_ck CHECK (effective_to IS NULL OR effective_to > effective_from),
    CONSTRAINT tender_definition_code_uq UNIQUE NULLS NOT DISTINCT (tenant_id, property_id, tender_code)
);

CREATE TABLE commerce.cart (
    cart_id                        uuid NOT NULL DEFAULT core.uuid_v7(),
    tenant_id                      uuid NOT NULL,
    property_id                    uuid NOT NULL,
    guest_id                       uuid,
    appointment_id                 uuid,
    visit_id                       uuid,
    currency_code                  char(3) NOT NULL,
    expires_at                     timestamptz,
    converted_order_id             uuid,
    status                         text NOT NULL DEFAULT 'Open',
    version                        integer NOT NULL DEFAULT 1,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT cart_pkey PRIMARY KEY (cart_id),
    CONSTRAINT cart_currency_code_ck CHECK (currency_code ~ '^[A-Z]{3}$'),
    CONSTRAINT cart_version_ck CHECK (version >= 1),
    CONSTRAINT cart_tenant_identity_uq UNIQUE (tenant_id, cart_id),
    CONSTRAINT cart_prop_ref_uq UNIQUE (tenant_id, property_id, cart_id),
    CONSTRAINT cart_status_known CHECK (status IN ('Open', 'Converted', 'Abandoned', 'Expired')),
    CONSTRAINT cart_converted_has_order CHECK ((status = 'Converted') = (converted_order_id IS NOT NULL))
);

CREATE TABLE commerce.cart_line (
    cart_line_id                   uuid NOT NULL DEFAULT core.uuid_v7(),
    tenant_id                      uuid NOT NULL,
    property_id                    uuid NOT NULL,
    cart_id                        uuid NOT NULL,
    line_number                    smallint NOT NULL,
    commerce_catalog_item_id       uuid NOT NULL,
    inventory_item_variant_id      uuid,
    appointment_id                 uuid,
    description                    text NOT NULL,
    quantity                       numeric(18,6) NOT NULL DEFAULT 1,
    unit_price_minor               bigint NOT NULL,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT cart_line_pkey PRIMARY KEY (cart_line_id),
    CONSTRAINT cart_line_line_number_ck CHECK (line_number >= 1),
    CONSTRAINT cart_line_quantity_ck CHECK (quantity > 0),
    CONSTRAINT cart_line_tenant_identity_uq UNIQUE (tenant_id, cart_line_id),
    CONSTRAINT cart_line_number_uq UNIQUE (tenant_id, cart_id, line_number)
);

CREATE TABLE commerce.commerce_order (
    commerce_order_id              uuid NOT NULL DEFAULT core.uuid_v7(),
    tenant_id                      uuid NOT NULL,
    property_id                    uuid NOT NULL,
    order_number                   text,
    guest_id                       uuid,
    appointment_id                 uuid,
    visit_id                       uuid,
    owner_system                   text NOT NULL DEFAULT 'Spa',
    ordered_at                     timestamptz NOT NULL DEFAULT now(),
    currency_code                  char(3) NOT NULL,
    subtotal_minor                 bigint NOT NULL DEFAULT 0,
    discount_total_minor           bigint NOT NULL DEFAULT 0,
    tax_total_minor                bigint NOT NULL DEFAULT 0,
    tip_total_minor                bigint NOT NULL DEFAULT 0,
    total_minor                    bigint NOT NULL DEFAULT 0,
    status                         text NOT NULL DEFAULT 'Draft',
    source_system                  text NOT NULL DEFAULT 'Spa',
    source_key                     text,
    version                        integer NOT NULL DEFAULT 1,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT commerce_order_pkey PRIMARY KEY (commerce_order_id),
    CONSTRAINT commerce_order_owner_system_ck CHECK (owner_system IN ('Spa', 'Marquee', 'Pos')),
    CONSTRAINT commerce_order_currency_code_ck CHECK (currency_code ~ '^[A-Z]{3}$'),
    CONSTRAINT commerce_order_discount_total_minor_ck CHECK (discount_total_minor >= 0),
    CONSTRAINT commerce_order_tax_total_minor_ck CHECK (tax_total_minor >= 0),
    CONSTRAINT commerce_order_tip_total_minor_ck CHECK (tip_total_minor >= 0),
    CONSTRAINT commerce_order_version_ck CHECK (version >= 1),
    CONSTRAINT commerce_order_tenant_identity_uq UNIQUE (tenant_id, commerce_order_id),
    CONSTRAINT commerce_order_prop_ref_uq UNIQUE (tenant_id, property_id, commerce_order_id),
    CONSTRAINT commerce_order_status_known CHECK (status IN ('Draft', 'Open', 'Delegated', 'PartiallyPaid', 'Paid', 'PartiallyRefunded', 'Refunded', 'Voided')),
    CONSTRAINT commerce_order_delegated_is_external CHECK (status <> 'Delegated' OR owner_system <> 'Spa')
);
COMMENT ON TABLE commerce.commerce_order IS 'When Marquee owns commerce for the property, owner_system = ''Marquee'' and source_key is its order id. [§53.2 Commerce; DEC-001 (owner_system); DEC-002 (Marquee owns delegated commerce)]';

