CREATE TRIGGER tender_definition_touch BEFORE UPDATE ON commerce.tender_definition FOR EACH ROW EXECUTE FUNCTION core.touch_versioned();
CREATE TRIGGER cart_touch BEFORE UPDATE ON commerce.cart FOR EACH ROW EXECUTE FUNCTION core.touch_versioned();
CREATE TRIGGER cart_line_touch BEFORE UPDATE ON commerce.cart_line FOR EACH ROW EXECUTE FUNCTION core.touch();
