CREATE TRIGGER payment_intent_touch BEFORE UPDATE ON commerce.payment_intent FOR EACH ROW EXECUTE FUNCTION core.touch_versioned();
CREATE TRIGGER payment_transaction_append_only BEFORE UPDATE OR DELETE ON commerce.payment_transaction FOR EACH ROW EXECUTE FUNCTION core.forbid_mutation();
CREATE TRIGGER refund_touch BEFORE UPDATE ON commerce.refund FOR EACH ROW EXECUTE FUNCTION core.touch_versioned();
CREATE TRIGGER deposit_ledger_entry_append_only BEFORE UPDATE OR DELETE ON commerce.deposit_ledger_entry FOR EACH ROW EXECUTE FUNCTION core.forbid_mutation();
CREATE TRIGGER receipt_touch BEFORE UPDATE ON commerce.receipt FOR EACH ROW EXECUTE FUNCTION core.touch_versioned();
CREATE TRIGGER commerce_reference_touch BEFORE UPDATE ON commerce.commerce_reference FOR EACH ROW EXECUTE FUNCTION core.touch_versioned();
CREATE TRIGGER visit_charge_reference_touch BEFORE UPDATE ON commerce.visit_charge_reference FOR EACH ROW EXECUTE FUNCTION core.touch();
